import{_ as a,o as e,c as i,ai as r}from"./chunks/framework.ampVZV4B.js";const m=JSON.parse('{"title":"[决策] 为何暂不用 MQTT / EMQX","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/industrial-digitalization/decisions/02-no-mqtt-yet.md","filePath":"tech-system/industrial-digitalization/decisions/02-no-mqtt-yet.md"}'),d={name:"tech-system/industrial-digitalization/decisions/02-no-mqtt-yet.md"};function l(o,t,n,s,h,c){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="决策-为何暂不用-mqtt-emqx" tabindex="-1"><code>[决策]</code> 为何暂不用 MQTT / EMQX <a class="header-anchor" href="#决策-为何暂不用-mqtt-emqx" aria-label="Permalink to “[决策] 为何暂不用 MQTT / EMQX”">​</a></h1><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>状态</td><td>🔵 设计中</td></tr><tr><td>类型</td><td><code>[决策]</code> Rejected（当前阶段）</td></tr><tr><td>项目</td><td>Mini MES V0</td></tr><tr><td>证据</td><td>待 Lab 001 / 002 对照</td></tr></tbody></table><hr><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>工业 IoT 资料常默认：设备/网关必须 MQTT + Broker。</p><h2 id="常见说法" tabindex="-1">常见说法 <a class="header-anchor" href="#常见说法" aria-label="Permalink to “常见说法”">​</a></h2><blockquote><p>IoT 项目就该上 MQTT / EMQX。</p></blockquote><h2 id="判断" tabindex="-1">判断 <a class="header-anchor" href="#判断" aria-label="Permalink to “判断”">​</a></h2><p><strong>不是标配，是需求驱动。</strong></p><p>V0 形态是「一个 Gateway → 一个后端」。HTTP 能完成上报、错误码清晰、排障简单。</p><p>MQTT 真正有价值的场景包括：多消费者（监控 + 报警 + 分析）、发布订阅解耦、弱网与会话、设备侧本就 MQTT。这些 <strong>V0 都不成立</strong>。</p><h2 id="暂不用的原因" tabindex="-1">暂不用的原因 <a class="header-anchor" href="#暂不用的原因" aria-label="Permalink to “暂不用的原因”">​</a></h2><ol><li>多一个 EMQX = 多一套部署、权限、QoS、残留会话问题</li><li>尚未有「第二个订阅方」证明 Broker 必要</li><li>想先用 Lab 001 把采集与存储的问题暴露出来，避免和消息层问题缠在一起</li></ol><h2 id="何时重新评估-v1-触发" tabindex="-1">何时重新评估（V1 触发） <a class="header-anchor" href="#何时重新评估-v1-触发" aria-label="Permalink to “何时重新评估（V1 触发）”">​</a></h2><ul><li>需要第二个独立消费者</li><li>或 Lab 明确要做 QoS / 断线补传对照</li><li>或 Gateway 数量与上报模型明显适合 pub/sub</li></ul><p>→ 对照实验：<a href="./../labs/lab-001.html">Lab 001</a> 之后的 Lab 002（规划中）</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h2><p>V0 <strong>不用</strong> MQTT/EMQX；V1 用实验数据决定，不凭口号上。</p>',18)])])}const p=a(d,[["render",l]]);export{m as __pageData,p as default};
